# src/components/social/__tests__/avisos-sesion-social.test.ts
    it("no queda ningún aviso suelto de «Inicia sesión» apuntando a /login", () => {
        for (const archivo of ["PostCard.tsx", "entity-header.tsx", "governance-entity-page.tsx"]) {
            const codigo = fuente(archivo);
            expect(codigo, `${archivo}: sin enlaces sueltos a /login`).not.toMatch(/href="\/login"/);
            // El candado del aviso suelto desaparece con el bloque; el texto solo vive en AvisoSesion
            // (y en el placeholder del cuadro de comentarios, que no es un aviso: la palabra
            // `placeholder` va hasta dos líneas por encima del texto del ternario).
            const lineas = codigo.split("\n");
            for (let i = 0; i < lineas.length; i++) {
                if (lineas[i].includes("Inicia sesión") && !lineas[i].includes("<AvisoSesion")) {
                    const contexto = lineas.slice(Math.max(0, i - 2), i).join(" ");
                    if (!contexto.includes("placeholder")) {
                        expect.fail(`${archivo}: aviso suelto fuera de AvisoSesion → ${lineas[i].trim()}`);
                    }
                }
            }
        }
    });

